import { readFileSync } from "node:fs";
import openapiTS, { astToString } from "openapi-typescript";

export const MARKETPLACE_TYPES_SCRIPT = "bun run marketplace:types";

const HEADER = `/**
 * GENERATED by \`${MARKETPLACE_TYPES_SCRIPT}\` from convex/lib/marketplace/openapi.marketplace.yaml. Do not edit.
 * Update the spec copy and contract.json together, then regenerate.
 */

`;

const SPEC_URL = new URL("../../convex/lib/marketplace/openapi.marketplace.yaml", import.meta.url);

export async function generateMarketplaceTypes(): Promise<string> {
  return HEADER + astToString(await openapiTS(readFileSync(SPEC_URL, "utf8")));
}
